#!/bin/bash
# scale.sh <tag> [sizes]: one design-iteration analysis (iteration 0) of the ST20 plates with src_v3 (plate.sh), then the
# Table 5 lattices (t5.sh). Layouts of 162+ cells are generated by gen_hlat.py into V3W/layouts (packets V3W/plate_packets).
TAG=$1; SIZES=${2:-"51 88 110 135 162"}
W=/root/autodl-tmp/OPL/V3W; P=/root/autodl-tmp/OPL
source $P/S1/env_gpu.sh
mkdir -p $W/layouts $W/plate_packets
for N in $SIZES; do
  LAY=$P/S1/V2/R1/SCALE/layouts/plateS$N.json
  if [ ! -f $LAY ]; then
    LAY=$W/layouts/plateS$N.json
    case $N in 162) S=11;; 190) S=12;; 222) S=13;; 256) S=14;; 296) S=15;; 336) S=16;; 378) S=17;; 424) S=18;; *) S=0;; esac
    if [ ! -f $LAY ] && [ $S != 0 ]; then
      B0=$(python3 -c "import math; t=math.radians(33.690067525979785); print(repr(math.cos(t)+$S*math.sin(t)/2))")
      (cd $P/src_v3 && $PY gen_hlat.py plateS$N --shape $S,$((2*S)),1 --theta-deg 33.690067525979785 --b0 $B0 --t0 0.40 --gx 0 --gy 0 --gz 0 \
        --jitter 0 --min-vol 0.05 --packets $W/plate_packets --out $W/layouts >> $W/layouts/gen.log 2>&1)
    fi
  fi
  LAYOUT=$LAY bash $W/scripts/plate.sh $TAG $N
done
echo "$(date +%F_%T) SCALE_${TAG}_DONE" >> $W/status.txt
